public int LengthOfLIS(int[] nums) {
    var dp = new int[nums.Length];   // dp[i]: самая длинная, кончается в i
    int best = 0;
    for (int i = 0; i < nums.Length; i++) {
        dp[i] = 1;
        for (int j = 0; j < i; j++)
            if (nums[j] < nums[i]) dp[i] = Math.Max(dp[i], dp[j] + 1);
        best = Math.Max(best, dp[i]);
    }
    return best;
}

